package com.quincaisoft.identity.application;
import com.quincaisoft.identity.api.IdentityBootstrapService;import com.quincaisoft.identity.infrastructure.*;import com.quincaisoft.shared.BootstrapScope;import jakarta.persistence.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import java.util.*;import java.time.*;
@Service public class DefaultIdentityBootstrapService implements IdentityBootstrapService { private final EntityManager em; public DefaultIdentityBootstrapService(EntityManager em){this.em=em;}
@Transactional(propagation=Propagation.MANDATORY) public void initialize(BootstrapScope s) {require(s);var m=new Membership();m.tenantId=s.tenantId();m.companyId=s.companyId();m.branchId=s.branchId();m.actorId=s.ownerId();m.roleCode="owner";m.active=true;m.authorizationEpoch=1;em.persist(m);em.flush();}
private void require(BootstrapScope s) { if(!em.isJoinedToTransaction()) throw new IllegalStateException("Bootstrap must join platform transaction"); Number n=(Number)em.createNativeQuery(BootstrapScope.AUTHORIZATION_SQL).setParameter("p",s.provisioningId()).setParameter("t",s.tenantId()).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setParameter("o",s.ownerId()).getSingleResult(); if(n.longValue()!=1)throw new org.springframework.security.access.AccessDeniedException("Approved current platform bootstrap required"); }
}
